const posts = tp.response.json();
tp.test('every post belongs to the user', () => {
  for (const p of posts) tp.expect(p.userId).to.eql(Number(tp.collectionVariables.get('userId')));
});
// pass the first post's id to the next requests
tp.collectionVariables.set('postId', posts[0].id);
console.log('Saved postId', posts[0].id);

const template = `
<style>table{border-collapse:collapse;font:13px system-ui}td,th{border:1px solid #ccc;padding:4px 8px;text-align:left}</style>
<table>
  <tr><th>#</th><th>Title</th></tr>
  {{#each posts}}<tr><td>{{id}}</td><td>{{title}}</td></tr>{{/each}}
</table>`;
tp.visualizer.set(template, { posts: tp.response.json() });

// Postman compatibility: this script uses Postman's pm.* API on purpose; TestPion runs it unchanged (write tp.* in your own scripts).
const user = pm.response.json();
pm.test('the server echoes the fake user', () => {
  pm.expect(user.email).to.match(/@example\.test$/);
  pm.expect(user.externalId).to.match(/^[0-9a-f-]{36}$/);
  pm.expect(user.address.city).to.not.include('{{');
});
console.log('created', user.name, 'from', user.address.city);

// Postman compatibility: this script uses Postman's pm.* API on purpose; TestPion runs it unchanged (write tp.* in your own scripts).
const posts = pm.response.json();
pm.test('every post has a title (lodash)', () => pm.expect(_.every(posts, 'title')).to.be.true);
pm.test('all from the same user (lodash)', () => pm.expect(_.uniq(_.map(posts, 'userId'))).to.eql([Number(pm.variables.get('userId'))]));
pm.test('matches the schema', () => pm.response.to.have.jsonSchema({
  type: 'array',
  items: { type: 'object', required: ['id', 'title', 'body', 'userId'], properties: { id: { type: 'integer' }, title: { type: 'string' } } },
}));
console.log('since', pm.variables.get('since'), '→', posts.length, 'posts');
